const $=id=>document.getElementById(id),manual2000=document.body.dataset.profile==='2000',clock=manual2000?new Hamilton2000Clock():new VisionTimeClock();
let sound=true,audio,last=performance.now(),drill=-1,passed=false;
const drills=[
{title:'Build a new game',text:'Follow the VisionTime setup sequence. The defaults are a 15-minute first period.',task:'NEW GAME → CLEAR → 1 → ENTER × 4',event:'newgame',check:()=>clock.period===1&&clock.time===900&&clock.down},
{title:'Puck drop, then whistle',text:'Run the game clock, then hold it when play stops.',task:'GAME TIMER RUN → GAME TIMER HOLD',event:'hold',check:()=>clock.time<900},
{title:'Correct the game time',text:'The referee asks you to put 14:30 back on the clock.',task:'SET TIMER → 14 → ENTER → 30 → ENTER → 0 → ENTER',event:'set',check:()=>clock.time===870},
{title:'A two-minute home penalty',text:'Enter a normal penalty for HOME #12. Minutes and seconds are separate fields.',task:'HOME PENALTY → ENTER → 12 → ENTER → 2 → ENTER → ENTER',event:'penalty',check:()=>clock.pen.home.some(p=>p.player===12&&p.remaining===120&&p.kind==='normal')},
{title:'Guest goal',text:'Add a goal for the guest team. A goal does not release a penalty by itself.',task:'GUEST SCORE',event:'score',check:()=>clock.guest===1},
{title:'Release the penalty',text:'The referee confirms that the minor penalty ends after this goal.',task:'RECALL → HOME PENALTY → CLEAR → ENTER',event:'delete',check:()=>clock.pen.home.length===0},
{title:'Correct a score',text:'Practise changing a total directly. Set the HOME score to 3.',task:'RECALL → HOME SCORE → 3 → ENTER',event:'correction',check:()=>clock.home===3},
{title:'Run an intermission',text:'Switch to the break clock and run it. Game time must stay at 14:30.',task:'INTERMISSION → GAME TIMER RUN',event:'run',check:()=>clock.view==='break'&&clock.time===870},
{title:'Return from the break',text:'Hold the break timer, then set its remaining time to zero.',task:'GAME TIMER HOLD → RECALL → INTERMISSION → 0 → ENTER → 0 → ENTER',event:'breakend',check:()=>clock.view==='game'&&clock.time===870},
{title:'Display the time of day',text:'Switch the scoreboard to Toronto’s current local time.',task:'RECALL → TIME OF DAY',event:'time',check:()=>clock.view==='time'},
{title:'Back to game time',text:'Restore the game clock display without changing its value.',task:'RECALL → SET TIMER',event:'return',check:()=>clock.view==='game'&&clock.time===870}
];
if(manual2000){drills[0].task='NEW GAME → CLEAR → 1 → ENTER × 3';drills[7].task='INTERMISSION → 3 → ENTER';drills[7].event='break';drills[8].task='TIMER HOLD → INTERMISSION → 0 → ENTER';drills[8].text='Cancel the break clock by entering a new intermission of zero minutes.';drills.push({title:'Time out, home',text:'Set a 30-second home timeout. The game clock stays held.',task:'HOME TIME OUT → ENTER',event:'timeout',check:()=>clock.view==='timeout'&&clock.timeoutTime===30},{title:'End the timeout early',text:'Enter zero seconds to return to game time.',task:'HOME TIME OUT → 0 → ENTER',event:'timeoutend',check:()=>clock.view==='game'},{title:'Record a shot on goal',text:'Add one shot for the home team.',task:'HOME SHOTS',event:'shots',check:()=>clock.shots.home===1});}
function lcdTime(t){const n=Math.floor(Math.max(0,t)*100+1e-6);return String(Math.floor(n/6000)).padStart(2,'0')+':'+String(Math.floor(n/100)%60).padStart(2,'0')+'.'+String(n%100).padStart(2,'0');}
function fmt(t,fraction=true){t=Math.max(0,t);if(t<60&&t>0&&fraction)return t.toFixed(2).padStart(5,'0');const n=Math.ceil(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function log(message){const li=document.createElement('li'),t=document.createElement('time');t.textContent=fmt(clock.time,false);li.append(t,document.createTextNode(message));$('log').prepend(li);while($('log').children.length>30)$('log').lastChild.remove();}
const hornAudio=new RinkHorn(()=>{clock.message='AUDIO BLOCKED · CHECK BROWSER SOUND';render();});
function horn(duration=.65){document.body.classList.add('honking');setTimeout(()=>document.body.classList.remove('honking'),duration*1000);if(sound)hornAudio.pulse(duration);else clock.message='HORN MUTED · TAP SOUND OFF TO ENABLE';}

function render(){
 $('clock').textContent=manual2000&&clock.testDisplay?String(Math.floor(performance.now()/1000)%10).repeat(4):clock.view==='timeout'?fmt(clock.timeoutTime):clock.view==='time'&&clock.todSeconds!==undefined?String(Math.floor(clock.todSeconds/3600)).padStart(2,'0')+':'+String(Math.floor(clock.todSeconds/60)%60).padStart(2,'0'):clock.view==='time'?new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()):fmt(clock.view==='break'?clock.breakTime:clock.time);
 $('clock-label').textContent=clock.view==='timeout'?'TIME OUT':clock.view==='time'?'TIME OF DAY':clock.view==='break'?(clock.period===0?'WARM-UP':'INTERMISSION'):'GAME TIME';
 $('status').textContent=clock.view==='time'?'● TIME OF DAY':(clock.view==='timeout'?'● TIME OUT · ':clock.view==='break'?'● INTERMISSION · ':'● GAME · ')+(clock.running?'RUN':'HOLD');$('period').textContent=clock.period;for(const side of ['home','guest'])if($(side+'-shots'))$(side+'-shots').textContent=clock.shots?.[side]||0;
 for(const side of ['home','guest']){$(side).textContent=clock[side];$(side+'-name').textContent=clock.names[side];$(side==='home'?'hp':'gp').textContent=clock.pen[side].slice(0,2).map(p=>'#'+p.player+' '+fmt(p.remaining,false)+(['delayed','delayedMisconduct'].includes(p.kind)?' HOLD':p.kind==='misconduct'?' M':'')).join('\n')||'—  —:——';}
 if($('penalty-memory')){for(const side of ['home','guest'])if($(side+'-shots'))$(side+'-shots').textContent=clock.shots[side];const memory=$('penalty-memory');memory.replaceChildren();for(const side of ['home','guest']){const label=document.createElement('b');label.textContent=side.toUpperCase()+' · '+clock.pen[side].length+'/15';memory.append(label);for(const p of clock.pen[side]){const row=document.createElement('p');row.textContent='#'+p.player+' · '+fmt(p.remaining,false)+' · '+p.kind;memory.append(row);}}}
 $('penstate').textContent=clock.penRunning?'PENALTIES RUN':'PENALTIES HOLD';$('prompt').textContent=clock.message;$('recall').setAttribute('aria-pressed',String(clock.recall));
 const e=clock.edit;if(!e)$('entry').textContent=clock.view==='timeout'?'TIME OUT '+fmt(clock.timeoutTime):clock.view==='break'?'BREAK '+fmt(clock.breakTime):'GAME '+(manual2000?lcdTime(clock.time):fmt(clock.time))+' · '+(clock.down?'DOWN':'UP');else if(e.type==='new')$('entry').textContent='CLEAR confirms · ESC cancels';else if(e.type==='name')$('entry').textContent=e.chars.map((c,i)=>i===e.pos?'['+c+']':c).join('');else if(e.type==='kind')$('entry').textContent=e.kind.toUpperCase();else if(e.type==='penRecall'){const p=clock.pen[e.side][e.slot];$('entry').textContent='LINE '+(e.slot+1)+' · #'+p.player+' '+fmt(p.remaining,false)+(manual2000?' · '+(e.newKind||p.kind)+' ['+(e.cursor||'player')+']':'')+(e.remove?' → REMOVE':'');}else $('entry').textContent=e.digits||'DEFAULT '+e.value+' · ENTER accepts';
}
function events(){for(const event of clock.events.splice(0)){if(event==='horn')horn(clock.hornSeconds||.65);else log(({newgame:'New game configured',run:'Timer running',hold:'Timer held',set:'Game time corrected',score:'Goal added',correction:'Score corrected',penalty:'Penalty entered',delete:'Penalty released',break:'Intermission display',breakend:'Back to game timer',time:'Time of day display',return:'Game display restored',expired:'Penalty expired',end:'Period complete',name:'Team name saved',penrun:'Penalty timers enabled',penhold:'Penalty timers held',released:'Delayed penalty released',timeout:'Team timeout running',timeoutend:'Timeout ended',shots:'Shots updated',auto:'Auto horn configured',breakfinished:'Break timer finished'})[event]||event);if(drill>=0&&!passed&&event===drills[drill].event&&drills[drill].check()){passed=true;$('task').textContent='✓ Complete. '+(drill===drills.length-1?'Practice shift finished.':'Continue when ready.');$('next').disabled=false;$('next').textContent=drill===drills.length-1?'Practise again ↻':'Next drill →';log('Drill '+(drill+1)+' complete');}}}
function key(k){if(k==='horn')horn();else clock.key(k);events();render();}
function free(){drill=-1;passed=false;$('free').classList.add('selected');$('guided').classList.remove('selected');$('tag').textContent='FREE PRACTICE';$('drilltitle').textContent='Learn the Hamilton sequence.';$('drilltext').textContent=manual2000?'Practise hockey controls from the HDD 2000-series manual.':'Practise the buttons on the Hamilton VisionTime controller.';$('task').textContent=manual2000?'NEW GAME → CLEAR → 1 → ENTER three times.':'NEW GAME → CLEAR → 1 → ENTER four times.';$('next').disabled=false;$('next').textContent='Start guided drills ↗';}
function next(){if(drill<0||drill===drills.length-1){clock.periodLength=900;clock.reset();drill=0;$('log').replaceChildren();}else drill++;passed=false;const d=drills[drill];$('tag').textContent=(manual2000?'2000 SERIES DRILL ':'VISIONTIME DRILL ')+(drill+1)+' / '+drills.length;$('drilltitle').textContent=d.title;$('drilltext').textContent=d.text;$('task').textContent=d.task;$('next').textContent='Complete the task to continue';$('next').disabled=true;$('guided').classList.add('selected');$('free').classList.remove('selected');render();}
const keypadKeys=manual2000?['7','8','9','+','4','5','6','-','1','2','3','clear','alt','0','enter','recall']:['1','2','3','+','4','5','6','-','7','8','9','clear','alt','0','enter','recall'];
for(const item of keypadKeys){const b=document.createElement('button');const letters={'1':'','2':'ABC','3':'DEF','4':'GHI','5':'JKL','6':'MNO','7':'PRS','8':'TUV','9':'WXY','0':'QZ'};const legends=manual2000?{alt:'HOLD PEN MEM',enter:'ENTER',recall:'RECALL',clear:'CLEAR','+':'+','-':'−'}:{alt:'*',enter:'#',recall:'D',clear:'C','+':'A','-':'B'};b.textContent=legends[item]||item;b.setAttribute('aria-label',manual2000?(legends[item]||item):({alt:'* ALT PEN',enter:'# ENTER',recall:'D RECALL',clear:'C CLEAR','+':'A ADVANCE','-':'B BACK'}[item]||item));b.dataset.key=item;if(!manual2000&&letters[item]){const small=document.createElement('small');small.textContent=letters[item];b.append(small);}if(!/^\d$/.test(item)){b.classList.add('command');if(!manual2000){const small=document.createElement('small');small.textContent={alt:'ALT PEN',enter:'ENTER',recall:'RECALL',clear:'CLEAR','+':'ADVANCE','-':'BACK'}[item];b.append(small);}}if(item==='recall'){b.id='recall';b.classList.add('recall');}if(item==='enter')b.classList.add('enter');$('keypad').append(b);}

document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>key(b.dataset.key));$('free').onclick=free;$('guided').onclick=()=>{if(drill<0)next();};$('next').onclick=next;$('reset').onclick=()=>{if(confirm('Reset the practice game?')){clock.periodLength=Number($('length').value);clock.reset();free();log('New practice game');render();}};$('length').onchange=()=>{clock.message='PERIOD LENGTH APPLIES ON RESET';render();};$('sound').onclick=()=>{sound=!sound;hornAudio.setMuted(!sound);$('sound').setAttribute('aria-pressed',String(sound));$('sound').textContent='Sound '+(sound?'on':'off');if(sound)horn();};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;let k;if(e.code==='Space'){if(e.target.tagName==='BUTTON')return;k=clock.running?'hold':'run';}else if(e.key==='Enter'){if(e.target.tagName==='BUTTON')return;k='enter';}else if(e.key==='Escape')k='cancel';else if(e.key.toLowerCase()==='h')k='horn';else if(!manual2000&&['*','#','a','b','c','d'].includes(e.key.toLowerCase()))k=({'*':'alt','#':'enter',a:'+',b:'-',c:'clear',d:'recall'})[e.key.toLowerCase()];else if(/^\d$/.test(e.key)||e.key==='+'||e.key==='-')k=e.key;else if(e.key==='Backspace'){e.preventDefault();if(clock.edit?.digits)clock.edit.digits=clock.edit.digits.slice(0,-1);render();return;}if(k){e.preventDefault();key(k);}});
setInterval(()=>{const now=performance.now();clock.tick((now-last)/1000*Number($('speed').value));last=now;events();render();},50);
document.querySelector(manual2000?'a[href="hamilton2000.html"]':'a[href="hamilton.html"]').setAttribute('aria-current','page');free();log('Hamilton practice console ready');render();

{
 let heldVoice=null;
 const manualHorn=document.querySelector('[data-key="horn"]');
 function hornDown(){document.body.classList.add('honking');if(!sound){clock.message='HORN MUTED · TAP SOUND OFF TO ENABLE';render();return;}if(!heldVoice)heldVoice=hornAudio.hold();}
 function hornUp(){document.body.classList.remove('honking');hornAudio.release(heldVoice);heldVoice=null;}
 manualHorn.onclick=e=>{if(e.detail===0)horn();};manualHorn.onpointerdown=e=>{manualHorn.setPointerCapture(e.pointerId);hornDown();};manualHorn.onpointerup=hornUp;manualHorn.onpointercancel=hornUp;manualHorn.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();hornDown();}};manualHorn.onkeyup=hornUp;window.addEventListener('blur',hornUp);
}
document.addEventListener('pointerdown',()=>{if(sound)hornAudio.unlock().catch(()=>{});},{once:true});
document.addEventListener('keydown',()=>{if(sound)hornAudio.unlock().catch(()=>{});},{once:true});
